// Panel-wide defaults. Webhook bodies may override followersUrl/runLabel
// (dry-run form); page loads post empty bodies and get these defaults.
// collectorStatusUrl uses ?fresh=1 so the user-triggered refresh always gets
// a live Facebook check, never the cache the Docker healthcheck relies on.
const incoming = ($input.first() || { json: {} }).json || {};
const body = incoming.body || {};
return [{ json: { novncUrl: 'https://fb-browser.jpfernandez.online/vnc.html', apiBase: '/webhook/giveaway/api', collectorStatusUrl: 'http://browser:5679/status?fresh=1', followersUrl: body.followersUrl || 'https://www.facebook.com/<your-page>/followers/', runLabel: body.runLabel || 'giveaway' } }];

const cfg = $('GUI Config').first().json;
let html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Giveaway Collector — Control Panel</title>
<style>
  :root {
    --bg: #0b0d12; --surface: #12151c; --surface-2: #0d0f15; --sunken: #08090c;
    --border: #232838; --border-soft: #1b1f2b;
    --text: #e6e9f0; --text-dim: #8b93a7; --text-faint: #5b6172;
