  .sub-msg { color: var(--text-dim); font-size: 13px; margin: 8px 0 0; }
  a { color: var(--accent); text-decoration: none; }
  a:hover { color: var(--accent-hover); text-decoration: underline; }
  label.field { display: block; margin-bottom: 14px; }
  label.field:last-child { margin-bottom: 0; }
  label.field .lbl {
    display: block; font-size: 11px; font-weight: 700; text-transform: uppercase;
    letter-spacing: 0.05em; color: var(--text-dim); margin-bottom: 6px;
  }
  input[type=text] {
    width: 100%; padding: 10px 12px; background: var(--surface-2); border: 1px solid var(--border);
    border-radius: var(--radius-sm); color: var(--text); font-size: 13.5px; font-family: inherit;
