  .btn {
    appearance: none; border: 1px solid transparent; border-radius: var(--radius-sm);
    padding: 10px 16px; font-size: 13.5px; font-weight: 700; font-family: inherit; cursor: pointer;
    transition: background .15s ease, border-color .15s ease, transform .05s ease, opacity .15s ease;
  }
  .btn:active:not(:disabled) { transform: translateY(1px); }
  .btn:disabled { opacity: 0.5; cursor: not-allowed; }
  .btn-primary { background: var(--accent); color: #0b0d12; }
  .btn-primary:hover:not(:disabled) { background: var(--accent-hover); }
  .btn-ghost { background: transparent; border-color: var(--border); color: var(--text); }
  .btn-ghost:hover:not(:disabled) { background: var(--surface-2); border-color: var(--text-faint); }
  .btn-danger-ghost { background: transparent; border-color: var(--border); color: var(--bad); }
  .btn-danger-ghost:hover:not(:disabled) { background: var(--bad-bg); border-color: var(--bad); }
  #msg { font-size: 13px; margin-top: 12px; min-height: 1.2em; }
  #msg.ok { color: var(--ok); } #msg.err { color: var(--bad); } #msg.muted { color: var(--text-dim); }
  .log-stats {
    display: flex; gap: 18px; flex-wrap: wrap; font-size: 12px; color: var(--text-dim);
    margin-bottom: 10px;
  }
  .log-stats b { color: var(--text); font-weight: 700; }
  #log {
    background: var(--sunken); border: 1px solid var(--border-soft); border-radius: 10px;
    padding: 10px 12px; height: 240px; overflow-y: auto;
    font-family: ui-monospace, "Cascadia Code", "SF Mono", Consolas, "Liberation Mono", monospace;
    font-size: 12px; line-height: 1.7;
  }
  #log .line { display: flex; gap: 10px; white-space: pre-wrap; word-break: break-word; }
  #log .t { color: var(--text-faint); flex: none; width: 64px; }
  #log .p { flex: none; font-weight: 700; text-transform: uppercase; font-size: 10.5px; letter-spacing: 0.03em; padding-top: 2px; }
  #log .m { color: #b7c0d4; }
  #log .p-loading, #log .p-starting { color: #60a5fa; }
  #log .p-auth { color: #c084fc; }
  #log .p-scrolling { color: var(--ok); }
  #log .p-done { color: var(--ok); }
  #log .p-error { color: var(--bad); }
  #log .empty { color: var(--text-faint); text-align: center; padding-top: 90px; }
  .stat-grid {
    display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px;
    margin-bottom: 16px;
  }
  .stat {
    background: var(--surface-2); border: 1px solid var(--border-soft); border-radius: 10px;
    padding: 12px 14px;
  }
  .stat .lbl { font-size: 10.5px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--text-dim); margin-bottom: 4px; }
  .stat .val { font-size: 21px; font-weight: 700; }
  .stat .val.ok { color: var(--ok); } .stat .val.bad { color: var(--bad); }
  .table-wrap { max-height: 320px; overflow-y: auto; border: 1px solid var(--border-soft); border-radius: 10px; margin-bottom: 14px; }
  table { border-collapse: collapse; width: 100%; font-size: 13px; }
  th {
    position: sticky; top: 0; background: var(--surface-2); text-align: left; padding: 8px 10px;
    font-size: 10.5px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-dim);
    border-bottom: 1px solid var(--border-soft);
  }
  td { padding: 7px 10px; border-bottom: 1px solid var(--border-soft); color: var(--text-dim); }
  tr:last-child td { border-bottom: none; }
  td.name { color: var(--text); }
  .empty-note { color: var(--text-faint); font-size: 13px; margin: 0; }
  pre#jsonView {
    display: none; background: var(--sunken); border: 1px solid var(--border-soft); border-radius: 10px;
    padding: 12px 14px; max-height: 360px; overflow: auto; font-size: 12px;
    font-family: ui-monospace, "Cascadia Code", "SF Mono", Consolas, monospace; color: #b7c0d4;
    margin: 0;
  }
</style>
</head>
<body>
<div class="wrap">
<header class="page">
  <h1>Giveaway Collector</h1>
  <p>Facebook follower collection and giveaway roulette prep.</p>
</header>

<div class="card">
  <h2>Facebook session</h2>
  <div class="row">
    <span class="badge muted" id="authBadge"><span class="dot"></span><span id="authBadgeText">checking…</span></span>
    <button class="btn btn-ghost" onclick="refresh()">Refresh status</button>
    <a id="novnc" href="__NOVNC_URL__" target="_blank" rel="noopener">Open the VPS browser (noVNC) to log in manually →</a>
  </div>
  <p class="sub-msg" id="authMsg"></p>
</div>

<div class="card">
  <h2>Configuration</h2>
  <label class="field">
    <span class="lbl">Followers URL</span>
    <input type="text" id="followersUrl" oninput="saveFieldsToStorage()">
  </label>
  <label class="field">
    <span class="lbl">Run label</span>
    <input type="text" id="runLabel" oninput="saveFieldsToStorage()">
  </label>
</div>

<div class="card">
  <h2>Run</h2>
  <div class="row">
    <button class="btn btn-primary" id="runBtn" onclick="runCollection()">Run collection</button>
    <button class="btn btn-danger-ghost" id="stopBtn" onclick="stopCollection()" disabled>Stop</button>
    <button class="btn btn-danger-ghost" onclick="clearPending()">Clear last result</button>
  </div>
  <p id="msg" class="muted"></p>
</div>

<div class="card">
  <h2>Live activity <span class="hint" id="logRunLabel"></span></h2>
  <div class="log-stats" id="logStats"></div>
  <div id="log"><p class="empty">No run yet. Click Run collection to watch it work here.</p></div>
</div>

<div class="card">
  <h2>Results</h2>
  <div id="summary"><p class="empty-note">No result yet. Run a collection first.</p></div>
  <div id="preview"></div>
  <div class="row" id="resultActions" style="display:none;">
    <button class="btn btn-ghost" onclick="downloadJson()">Download JSON</button>
    <button class="btn btn-ghost" id="viewJsonBtn" onclick="toggleJson()">View raw JSON</button>
  </div>
  <pre id="jsonView"></pre>
</div>

</div>
<script>
var API = '__API_BASE__';
var currentRunId = null;
var renderedLogCount = 0;
var loggedRunId = null;
var pollTimer = null;
var jsonVisible = false;
var jsonCache = null;
// This page's own load already went through HTTP Basic Auth (the browser's
// native login popup), but browsers do not reliably reuse those cached
// credentials for background fetch() calls to sibling API paths (confirmed:
// a live 401 on /api/state even with the same realm as the page). So this
// page asks once for the same credentials and attaches them explicitly to
// every API call instead of depending on browser-specific reuse behavior.
var AUTH = null;
function ensureAuth() {
  if (AUTH) return AUTH;
  var u = prompt('Panel username (same login used to open this page):');
  var p = prompt('Panel password:');
  AUTH = 'Basic ' + btoa((u || '') + ':' + (p || ''));
  return AUTH;
}
function authHeaders(extra) {
  return Object.assign({ Authorization: ensureAuth() }, extra || {});
}
function handleAuthFailure() {
  AUTH = null;
  say('Authentication failed — check the username/password and try again (it will re-prompt on the next action).', 'err');
}
function say(t, kind) {
  var el = document.getElementById('msg');
  el.textContent = t;
  el.className = kind || 'muted';
}
function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;')
    .replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function setBadge(state, text) {
  var b = document.getElementById('authBadge');
  b.className = 'badge ' + state;
  document.getElementById('authBadgeText').textContent = text;
}
function fmtTime(ms) {
  var d = new Date(ms);
  function pad(n) { return (n < 10 ? '0' : '') + n; }
  return pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
}

// Followers URL / run label are remembered per-browser via localStorage —
// the server has no durable record of what was typed (only of completed
// run results), and re-populating these fields from a hardcoded server
// default on every refresh() previously clobbered whatever the operator had
// typed, including right after their own run finished. localStorage can be
// unavailable (private browsing, blocked site data) or throw, so every
// access is wrapped and the page still works with plain in-memory fields.
var LS_URL_KEY = 'giveawayPanel.followersUrl';
var LS_LABEL_KEY = 'giveawayPanel.runLabel';
function lsGet(key) {
  try { return window.localStorage.getItem(key); } catch (e) { return null; }
}
function lsSet(key, val) {
  try { window.localStorage.setItem(key, val); } catch (e) { /* ignore — not critical */ }
}
function saveFieldsToStorage() {
  lsSet(LS_URL_KEY, document.getElementById('followersUrl').value);
  lsSet(LS_LABEL_KEY, document.getElementById('runLabel').value);
}
var fieldsInitialized = false;
function initFieldsOnce(serverDefaults) {
  if (fieldsInitialized) return;
  fieldsInitialized = true;
  var savedUrl = lsGet(LS_URL_KEY);
  var savedLabel = lsGet(LS_LABEL_KEY);
  var urlEl = document.getElementById('followersUrl');
  var labelEl = document.getElementById('runLabel');
  urlEl.value = savedUrl || (serverDefaults && serverDefaults.followersUrl) || '';
  labelEl.value = savedLabel || (serverDefaults && serverDefaults.runLabel) || '';
}

function refresh() {
  setBadge('muted', 'checking…');
  fetch(API + '/state', { headers: authHeaders() }).then(function (r) {
    if (r.status === 401) { handleAuthFailure(); throw new Error('unauthorized'); }
    if (!r.ok) { throw new Error('HTTP ' + r.status); }
    return r.json();
  }).then(function (s) {
    setBadge(s.authenticated ? 'ok' : 'bad', s.authenticated ? 'Logged in' : 'Login required');
    document.getElementById('authMsg').textContent =
      (s.authMessage || '') + (s.facebookReachable === false ? ' (Facebook unreachable)' : '');
    initFieldsOnce(s.config);
    if (s.pending) {
      currentRunId = s.pending.runId;
      loadResults(currentRunId);
    } else {
      currentRunId = null;
    }
  }).catch(function (e) { if (e.message !== 'unauthorized') setBadge('bad', 'Error'); });
}

function setRunningUi(running) {
  document.getElementById('runBtn').disabled = running;
  document.getElementById('stopBtn').disabled = !running;
}

var lastRunStartedAt = 0;

function runCollection() {
  say('Starting collection…', 'muted');
  saveFieldsToStorage();
  lastRunStartedAt = Date.now();
  setRunningUi(true);
  resetLog();
  fetch(API + '/dry-run', {
    method: 'POST', headers: authHeaders({ 'Content-Type': 'application/json' }),
    body: JSON.stringify({
      followersUrl: document.getElementById('followersUrl').value,
      runLabel: document.getElementById('runLabel').value
    })
  }).then(function (r) {
    if (r.status === 401) { handleAuthFailure(); throw new Error('unauthorized'); }
    if (!r.ok) { throw new Error('HTTP ' + r.status); }
    say('Collection started — watch it work below.', 'ok');
    startPolling();
  }).catch(function (e) {
    if (e.message !== 'unauthorized') say('Run error: ' + e, 'err');
    setRunningUi(false);
  });
}

// /dry-run responds as soon as n8n accepts the webhook, before the
// followers-url payload has actually reached server.js's /collect (it still
// has to traverse Dry Config -> Build Dry Input -> Execute Collector ->
// Giveaway Config -> the HTTP node). If the operator hits Stop inside that
// short window, server.js sees collectBusy === false and reports "nothing
// to stop" even though a run is about to start — auto-retry for a few
// seconds after Run was clicked instead of taking that at face value.
var STOP_RACE_GRACE_MS = 20000;
var STOP_RETRY_DELAY_MS = 1500;
var STOP_MAX_RETRIES = 8;
function stopCollection(attempt) {
  attempt = attempt || 0;
  document.getElementById('stopBtn').disabled = true;
  say('Stopping…', 'muted');
  fetch(API + '/stop', { method: 'POST', headers: authHeaders() }).then(function (r) {
    if (r.status === 401) { handleAuthFailure(); throw new Error('unauthorized'); }
    if (!r.ok) { throw new Error('HTTP ' + r.status); }
    return r.json();
  }).then(function (j) {
    if (j.ok) {
      say('Stop requested — the run will end after its current scroll cycle.', 'muted');
      return;
    }
    if (typeof j.ok === 'undefined') {
      say('Could not reach the collector to stop it' + (j.error ? (': ' + j.error) : '') + '. Try again.', 'err');
      document.getElementById('stopBtn').disabled = false;
      return;
    }
    var withinGraceWindow = (Date.now() - lastRunStartedAt) < STOP_RACE_GRACE_MS;
    if (withinGraceWindow && attempt < STOP_MAX_RETRIES) {
      say('Waiting for the run to register before stopping…', 'muted');
      setTimeout(function () { stopCollection(attempt + 1); }, STOP_RETRY_DELAY_MS);
      return;
    }
    say(j.error || 'Nothing to stop.', 'muted');
    document.getElementById('stopBtn').disabled = false;
  }).catch(function (e) {
    if (e.message !== 'unauthorized') say('Stop error: ' + e, 'err');
    document.getElementById('stopBtn').disabled = false;
  });
}

function resetLog() {
  renderedLogCount = 0;
  loggedRunId = null;
  document.getElementById('log').innerHTML = '';
  document.getElementById('logStats').textContent = '';
  document.getElementById('logRunLabel').textContent = '';
}

function startPolling() {
  if (pollTimer) return;
  pollProgress();
  pollTimer = setInterval(pollProgress, 1500);
}

function stopPolling() {
  if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
}

function pollProgress() {
  fetch(API + '/progress', { headers: authHeaders() }).then(function (r) {
    if (r.status === 401) { handleAuthFailure(); throw new Error('unauthorized'); }
    if (!r.ok) { throw new Error('HTTP ' + r.status); }
    return r.json();
  }).then(function (p) { renderProgress(p); }).catch(function (e) {
    if (e.message !== 'unauthorized') { /* transient — next poll will retry */ }
  });
}

function renderProgress(p) {
  var logEl = document.getElementById('log');
  if (p.runId && p.runId !== loggedRunId) {
    loggedRunId = p.runId;
    renderedLogCount = 0;
    logEl.innerHTML = '';
  }
  document.getElementById('logRunLabel').textContent = p.runId ? ('· ' + p.runId) : '';
  var log = p.log || [];
  if (log.length && renderedLogCount === 0 && logEl.querySelector('.empty')) {
    logEl.innerHTML = '';
  }
  var wasNearBottom = (logEl.scrollHeight - logEl.scrollTop - logEl.clientHeight) < 40;
  for (var i = renderedLogCount; i < log.length; i++) {
    var e = log[i];
    var row = document.createElement('div');
    row.className = 'line';
    row.innerHTML = '<span class="t">' + fmtTime(e.at) + '</span>' +
      '<span class="p p-' + esc(e.phase || '') + '">' + esc(e.phase || '') + '</span>' +
      '<span class="m">' + esc(e.message || '') + '</span>';
    logEl.appendChild(row);
  }
  renderedLogCount = log.length;
  if (wasNearBottom) logEl.scrollTop = logEl.scrollHeight;

  var stats = document.getElementById('logStats');
  if (p.phase && p.phase !== 'idle') {
    stats.innerHTML =
      'Scrolls: <b>' + (p.scrollAttempts || 0) + '</b> · ' +
      'Encountered: <b>' + (p.totalEncountered || 0) + '</b> · ' +
      'Unique: <b>' + (p.uniqueFollowers || 0) + '</b>';
  }

  if (p.active === false && pollTimer) {
    stopPolling();
    setRunningUi(false);
    if (p.phase === 'error') {
      say('Collection stopped: ' + (p.error || 'unknown error') + '. See log above.', 'err');
    } else if (p.stopReason === 'canceled') {
      say('Collection stopped by operator. Loading results…', 'ok');
    } else if (p.phase === 'done') {
      say('Collection finished. Loading results…', 'ok');
    }
    refresh();
  }
}

function loadResults(runId) {
  fetch(API + '/results?runId=' + encodeURIComponent(runId), { headers: authHeaders() })
    .then(function (r) {
      if (r.status === 401) { handleAuthFailure(); throw new Error('unauthorized'); }
      if (!r.ok) { throw new Error('HTTP ' + r.status); }
      return r.json();
    }).then(function (j) {
      if (!j.summary) {
        document.getElementById('summary').innerHTML = '<p class="empty-note">No summary yet.</p>';
        document.getElementById('resultActions').style.display = 'none';
        return;
      }
      var s = j.summary;
      document.getElementById('summary').innerHTML =
        '<div class="stat-grid">' +
        '<div class="stat"><div class="lbl">Encountered</div><div class="val">' + s.totalEncountered + '</div></div>' +
        '<div class="stat"><div class="lbl">Unique followers</div><div class="val">' + s.uniqueFollowers + '</div></div>' +
        '<div class="stat"><div class="lbl">Duplicates</div><div class="val">' + s.duplicatesRemoved + '</div></div>' +
        '<div class="stat"><div class="lbl">Invalid / missing</div><div class="val">' + (s.invalidIds + s.missingNames) + '</div></div>' +
        '<div class="stat"><div class="lbl">Roulette entries</div><div class="val ' + (s.finalRouletteCount > 0 ? 'ok' : 'bad') + '">' + s.finalRouletteCount + '</div></div>' +
        '<div class="stat"><div class="lbl">Stop reason</div><div class="val" style="font-size:14px;">' + esc(s.stopReason) + '</div></div>' +
        '</div>';
      var rows = j.preview || [];
      var h = '<div class="table-wrap"><table><tr><th>Name</th><th>Profile ID</th><th>URL</th></tr>';
      rows.forEach(function (r) {
        h += '<tr><td class="name">' + esc(r.displayName) + '</td><td>' + esc(r.profileId) +
          '</td><td>' + esc(r.profileUrl) + '</td></tr>';
      });
      h += '</table></div><p class="empty-note">Showing ' + rows.length + ' of ' + j.previewTotal + ' roulette entries — download the full JSON below for everything.</p>';
      document.getElementById('preview').innerHTML = h;
      document.getElementById('resultActions').style.display = 'flex';
      jsonCache = null;
      jsonVisible = false;
      document.getElementById('jsonView').style.display = 'none';
      document.getElementById('viewJsonBtn').textContent = 'View raw JSON';
    }).catch(function (e) { if (e.message !== 'unauthorized') say('Results error: ' + e, 'err'); });
}

function fetchFullResults() {
  if (!currentRunId) return Promise.reject(new Error('no run selected'));
  if (jsonCache) return Promise.resolve(jsonCache);
  return fetch(API + '/results?runId=' + encodeURIComponent(currentRunId) + '&full=1', { headers: authHeaders() })
    .then(function (r) {
      if (r.status === 401) { handleAuthFailure(); throw new Error('unauthorized'); }
      if (!r.ok) { throw new Error('HTTP ' + r.status); }
      return r.json();
    }).then(function (j) { jsonCache = j; return j; });
}

function downloadJson() {
  fetchFullResults().then(function (j) {
    var blob = new Blob([JSON.stringify(j, null, 2)], { type: 'application/json' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'giveaway-' + (j.runId || 'results') + '.json';
    document.body.appendChild(a);
    a.click();
    a.remove();
